    model,
    messages: messages.map(m => ({ role: m.role, content: m.content })),
    stream: false,
    options: {
      num_ctx: 4096,
      temp: opts?.temperature ?? 0.7,
      top_p: opts?.topP ?? 0.95,
      stop: opts?.stop ?? [],
      num_predict: opts?.maxTokens ?? 2048,
    },
  });
