  // parse last human response
  let lastHuman = '';
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i].role === 'user') { lastHuman = messages[i].content; break; }
  }
  const end = stdout.lastIndexOf(lastHuman);
  return stdout.slice(end + lastHuman.length).trim();
}
